<?php

namespace App\Console\Commands;

use Illuminate\Console\Command;
use Illuminate\Support\Facades\DB;

class SeedVikasData extends Command
{
    protected $signature   = 'app:seed-vikas-data {salesperson_id=490}';
    protected $description = 'Seed Vikas Kamlakar sales pipeline demo data';

    // Positions 0-64 → encoded month key
    // "-s" suffix = sale, "-p" suffix = pending; no suffix = sale only
    private array $monthMap = [
        0=>'2026-06-s', 1=>'2026-06-p', 2=>'2026-05-s', 3=>'2026-05-p',
