       52=>'2022-04',  53=>'2022-03',  54=>'2022-02',  55=>'2022-01',
       56=>'2021-12',  57=>'2021-11',  58=>'2021-10',  59=>'2021-09',
       60=>'2021-08',  61=>'2021-07',  62=>'2021-06',  63=>'2021-05',
       64=>'2021-04',
    ];

    public function handle(): int
    {
        $spId = (int) $this->argument('salesperson_id');
        $user = DB::table('users')->find($spId);
        if (!$user) {
            $this->error("User {$spId} not found.");
            return 1;
        }

        $this->info("Seeding for: {$user->name} (ID {$spId})");

        // Wipe existing pipeline data for this salesperson
        $existingIds = DB::table('sales_pipelines')
            ->where('salesperson_id', $spId)
            ->pluck('id');

        if ($existingIds->isNotEmpty()) {
            DB::table('sales_pipeline_months')
                ->whereIn('sales_pipeline_id', $existingIds)
                ->delete();
            DB::table('sales_pipelines')
                ->where('salesperson_id', $spId)
                ->delete();
        }

        $tenantId = $user->tenant_id; // null for demo user
        $now  = now()->toDateTimeString();
        $rows = $this->getData();

        $bar = $this->output->createProgressBar(count($rows));
        $bar->start();

        foreach ($rows as [$name, $type, $razor, $upgrade, $brand, $bp, $monthly]) {
            // Upsert sales client
            $client   = DB::table('sales_clients')->where('name', $name)->first();
            $clientId = $client?->id ?? DB::table('sales_clients')->insertGetId([
                'name'       => $name,
                'tenant_id'  => null,
                'created_at' => $now,
                'updated_at' => $now,
            ]);

            $pipelineId = DB::table('sales_pipelines')->insertGetId([
                'party_name'               => $name,
                'salesperson_id'           => $spId,
                'type'                     => $type,
                'product'                  => $brand,
                'total_business_potential' => $bp,
                'is_locked'                => 1,
                'razor_blade'              => $razor ? 1 : 0,
                'upgrade'                  => $upgrade ? 1 : 0,
                'rate_increase'            => 0,
                'tenant_id'                => $tenantId,
                'created_at'               => $now,
                'updated_at'               => $now,
            ]);

            // Accumulate sale/pending per month_year
            $accum = [];
            foreach ($monthly as $i => $v) {
                if ($v === null) continue;
                $key = $this->monthMap[$i];
                $mk  = substr($key, 0, 7); // YYYY-MM
                if (str_ends_with($key, '-p')) {
                    $accum[$mk]['pending'] = (float) $v;
                } else {
                    $accum[$mk]['sale'] = (float) $v;
                }
            }

            $inserts = [];
            foreach ($accum as $mk => $vals) {
                $sale    = $vals['sale']    ?? 0;
                $pending = $vals['pending'] ?? 0;
                if ($sale > 0 || $pending > 0) {
                    $inserts[] = [
                        'sales_pipeline_id' => $pipelineId,
                        'month_year'        => $mk,
                        'sale_amount'       => $sale,
                        'pending_amount'    => $pending,
                        'forecast_amount'   => 0,
                        'tenant_id'         => $tenantId,
                        'created_at'        => $now,
                        'updated_at'        => $now,
                    ];
                }
            }

            foreach (array_chunk($inserts, 50) as $chunk) {
                DB::table('sales_pipeline_months')->insert($chunk);
            }

            $bar->advance();
        }

        $bar->finish();
        $this->newLine();
        $this->info("Done — seeded " . count($rows) . " clients for salesperson ID {$spId}.");
        return 0;
    }

